//! The port's layout and cursor functions against react-resizable-panels
//! 4.22.1's own, over the seeded cases in tests/fixtures/rrp-oracle.json
//! (generated by tools/rrp-oracle/generate.mjs). Every output must match
//! exactly: the same f64, or the same error.

use sample_interactions::panels::cursor::{cursor_style, CursorAxis, InteractionState};
use sample_interactions::panels::layout::{
    adjust_layout_by_delta, calculate_default_layout, separator_aria_values, validate_axis_layout,
    validate_item_size, ItemConstraints, Trigger,
};
use sample_interactions::panels::number::format_layout_number;
use sample_interactions::panels::Orientation;
use serde_json::Value;

const FIXTURE: &str = include_str!("fixtures/rrp-oracle.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("fixture JSON")
}

fn number(value: &Value) -> f64 {
    value.as_f64().expect("number")
}

fn optional(value: &Value) -> Option<f64> {
    value.as_f64()
}

/// `[collapsedSize, collapsedThreshold, collapsible, defaultSize, disabled,
/// maxSize, minSize]`.
fn constraint(value: &Value) -> ItemConstraints {
    let fields = value.as_array().expect("constraint array");
    ItemConstraints {
        collapsed_size: number(&fields[0]),
        collapsed_threshold: optional(&fields[1]),
        collapsible: fields[2].as_u64() == Some(1),
        default_size: optional(&fields[3]),
        disabled: fields[4].as_u64() == Some(1),
        max_size: number(&fields[5]),
        min_size: number(&fields[6]),
    }
}

fn constraints(value: &Value) -> Vec<ItemConstraints> {
    value
        .as_array()
        .expect("constraints")
        .iter()
        .map(constraint)
        .collect()
}

fn numbers(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .expect("numbers")
        .iter()
        .map(number)
        .collect()
}

fn trigger(name: &str) -> Trigger {
    match name {
        "imperative-api" => Trigger::ImperativeApi,
        "keyboard" => Trigger::Keyboard,
        "mouse-or-touch" => Trigger::MouseOrTouch,
        other => panic!("unknown trigger {other}"),
    }
}

/// Bitwise equality, so that 0.1 + 0.2 never passes for 0.3.
fn same(a: f64, b: f64) -> bool {
    a.to_bits() == b.to_bits() || (a == 0.0 && b == 0.0)
}

fn same_layout(a: &[f64], b: &[f64]) -> bool {
    a.len() == b.len() && a.iter().zip(b).all(|(a, b)| same(*a, *b))
}

struct Tally {
    name: &'static str,
    total: usize,
    failures: Vec<String>,
}

impl Tally {
    fn new(name: &'static str) -> Self {
        Self {
            name,
            total: 0,
            failures: Vec::new(),
        }
    }

    fn check(&mut self, ok: bool, describe: impl FnOnce() -> String) {
        self.total += 1;
        if !ok && self.failures.len() < 10 {
            self.failures.push(describe());
        } else if !ok {
            self.failures.push(String::new());
        }
    }

    fn finish(self) {
        println!(
            "ORACLE {}: {}/{} match react-resizable-panels 4.22.1",
            self.name,
            self.total - self.failures.len(),
            self.total
        );
        let shown: Vec<&String> = self
            .failures
            .iter()
            .filter(|text| !text.is_empty())
            .collect();
        assert!(
            self.failures.is_empty(),
            "{} mismatches, first: {shown:#?}",
            self.failures.len()
        );
    }
}

#[test]
fn format_layout_number_matches() {
    let fixture = fixture();
    let mut tally = Tally::new("formatLayoutNumber");
    for case in fixture["cases"]["formatLayoutNumber"].as_array().unwrap() {
        let value = number(&case["value"]);
        let expected = number(&case["result"]);
        let actual = format_layout_number(value);
        tally.check(same(actual, expected), || {
            format!("{value} -> {actual}, expected {expected}")
        });
    }
    tally.finish();
}

#[test]
fn validate_item_size_matches() {
    let fixture = fixture();
    let mut tally = Tally::new("validateItemSize");
    for case in fixture["cases"]["validateItemSize"].as_array().unwrap() {
        let item = constraint(&case["constraints"]);
        let expected = number(&case["result"]);
        let actual = validate_item_size(
            case["overrideDisabledItems"].as_bool().unwrap(),
            &item,
            number(&case["prevSize"]),
            number(&case["size"]),
        );
        tally.check(same(actual, expected), || format!("{case} -> {actual}"));
    }
    tally.finish();
}

#[test]
fn adjust_layout_by_delta_matches() {
    let fixture = fixture();
    let mut tally = Tally::new("adjustLayoutByDelta");
    for case in fixture["cases"]["adjustLayoutByDelta"].as_array().unwrap() {
        let items = constraints(&case["constraints"]);
        let initial = numbers(&case["initialLayout"]);
        let previous = if case["prevLayout"].is_null() {
            initial.clone()
        } else {
            numbers(&case["prevLayout"])
        };
        let pivots = numbers(&case["pivotIndices"]);
        let pivots = [pivots[0] as usize, pivots[1] as usize];
        let delta = number(&case["delta"]);
        for (name, result) in case["triggers"]
            .as_array()
            .unwrap()
            .iter()
            .zip(case["results"].as_array().unwrap())
        {
            let actual = adjust_layout_by_delta(
                delta,
                &initial,
                &items,
                pivots,
                &previous,
                trigger(name.as_str().unwrap()),
            );
            let ok = match (&actual, result.get("ok")) {
                (Ok(layout), Some(expected)) => same_layout(layout, &numbers(expected)),
                (Err(_), None) => true,
                _ => false,
            };
            tally.check(ok, || format!("{case} [{name}] -> {actual:?}"));
        }
    }
    tally.finish();
}

#[test]
fn validate_axis_layout_matches() {
    let fixture = fixture();
    let mut tally = Tally::new("validateAxisLayout");
    for case in fixture["cases"]["validateAxisLayout"].as_array().unwrap() {
        let items = constraints(&case["constraints"]);
        let layout = numbers(&case["layout"]);
        let actual = validate_axis_layout(&layout, &items);
        let ok = match (&actual, case.get("ok")) {
            (Ok(layout), Some(expected)) => same_layout(layout, &numbers(expected)),
            (Err(error), None) => case["error"].as_str() == Some(error.0.as_str()),
            _ => false,
        };
        tally.check(ok, || format!("{case} -> {actual:?}"));
    }
    tally.finish();
}

#[test]
fn calculate_default_layout_matches() {
    let fixture = fixture();
    let mut tally = Tally::new("calculateDefaultLayout");
    for case in fixture["cases"]["calculateDefaultLayout"]
        .as_array()
        .unwrap()
    {
        let actual = calculate_default_layout(&constraints(&case["constraints"]));
        tally.check(same_layout(&actual, &numbers(&case["result"])), || {
            format!("{case} -> {actual:?}")
        });
    }
    tally.finish();
}

#[test]
fn separator_aria_values_match() {
    let fixture = fixture();
    let mut tally = Tally::new("calculateSeparatorAriaValues");
    for case in fixture["cases"]["separatorAriaValues"].as_array().unwrap() {
        let items = constraints(&case["constraints"]);
        let layout = numbers(&case["layout"]);
        let index = case["itemIndex"].as_u64().unwrap() as usize;
        let actual = separator_aria_values(&layout, &items, index);
        let ok = match (&actual, case.get("ok")) {
            (Ok(values), Some(expected)) => same_layout(
                &[values.value_min, values.value_max, values.value_now],
                &numbers(expected),
            ),
            (Err(_), None) => true,
            _ => false,
        };
        tally.check(ok, || format!("{case} -> {actual:?}"));
    }
    tally.finish();
}

#[test]
fn cursor_style_matches() {
    let fixture = fixture();
    let mut tally = Tally::new("getCursorStyle");
    for case in fixture["cases"]["cursorStyle"].as_array().unwrap() {
        let state = match case["state"].as_str().unwrap() {
            "inactive" => InteractionState::Inactive,
            "hover" => InteractionState::Hover,
            "active" => InteractionState::Active,
            other => panic!("unknown state {other}"),
        };
        let disable_cursor = case["disableCursor"].as_bool().unwrap();
        let axes: Vec<CursorAxis> = case["orientations"]
            .as_array()
            .unwrap()
            .iter()
            .map(|orientation| CursorAxis {
                orientation: match orientation.as_str().unwrap() {
                    "horizontal" => Orientation::Horizontal,
                    _ => Orientation::Vertical,
                },
                disable_cursor,
            })
            .collect();
        let actual = cursor_style(case["cursorFlags"].as_u64().unwrap() as u8, &axes, state);
        tally.check(actual == case["result"].as_str(), || {
            format!("{case} -> {actual:?}")
        });
    }
    tally.finish();
}
